import itertools
from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=float)
def compute_area(p1, p2, p3):
    return 0.5 * abs(p1[0]*(p2[1]-p3[1]) + p2[0]*(p3[1]-p1[1]) + p3[0]*(p1[1]-p2[1]))

@task(returns=float)
def compare_areas(area1, area2):
    return min(area1, area2)

def main(points):

    areas = []
    for p1, p2, p3 in itertools.combinations(points, 3):
        area = compute_area(p1, p2, p3)
        areas.append(area)

    while len(areas) > 1:
        new_level = []
        for i in range(0, len(areas), 2):
            if i + 1 < len(areas):
                new_level.append(compare_areas(areas[i], areas[i+1]))
            else:
                new_level.append(areas[i])
        areas = new_level


    return compss_wait_on(areas[0])
